const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbols={alpha:'α',beta:'β',gamma:'γ',delta:'δ',Delta:'Δ',epsilon:'ε',theta:'θ',lambda:'λ',mu:'μ',pi:'π',rho:'ρ',sigma:'σ',Sigma:'Σ',phi:'φ',omega:'ω',Omega:'Ω',infty:'∞',times:'×',cdot:'·',pm:'±',div:'÷',le:'≤',leq:'≤',ge:'≥',geq:'≥',ne:'≠',neq:'≠',approx:'≈',to:'→',rightarrow:'→',leftarrow:'←',leftrightarrow:'↔',Rightarrow:'⇒',in:'∈',notin:'∉',subset:'⊂',cup:'∪',cap:'∩',forall:'∀',exists:'∃',partial:'∂',nabla:'∇',sum:'∑',prod:'∏',int:'∫',ldots:'…',sin:'sin',cos:'cos',tan:'tan',log:'log',ln:'ln',lim:'lim'};
export function parseMath(input){if(input.length>10000)throw Error('Use fórmulas de até 10.000 caracteres.');let pos=0,depth=0;const atom=()=>{while(input[pos]===' ')pos++;const c=input[pos++];if(!c)return{type:'text',text:''};if(c==='{'){if(++depth>60)throw Error('A fórmula tem grupos demais.');const n=row('}');depth--;return n}if(c==='\\'){const match=/^[a-zA-Z]+/.exec(input.slice(pos));if(!match){const ch=input[pos++]||' ';return{type:'text',text:ch===' '?' ':ch}}pos+=match[0].length;const cmd=match[0];if(['frac','dfrac','tfrac'].includes(cmd))return{type:'frac',a:atom(),b:atom()};if(cmd==='sqrt')return{type:'sqrt',a:atom()};if(cmd==='xrightarrow')return{type:'over',a:{type:'text',text:'⟶'},b:atom()};if(cmd==='text'||cmd==='mathrm'||cmd==='operatorname'){const n=atom();return{type:'normal',a:n}}if(cmd==='left'||cmd==='right')return atom();if(cmd==='quad'||cmd==='qquad')return{type:'text',text:cmd==='quad'?' ':'  '};if(symbols[cmd])return{type:'text',text:symbols[cmd]};throw Error(`Comando \\${cmd} não suportado. Use frações, raízes, potências, índices, símbolos gregos e operadores.`)}return{type:'text',text:c}};
const row=end=>{const children=[];while(pos<input.length){if(end&&input[pos]===end){pos++;return{type:'row',children}}if(input[pos]==='}'){throw Error('Há uma chave de fechamento sem abertura.')}if(input[pos]===' '){pos++;children.push({type:'text',text:' '});continue}let n=atom();while(input[pos]==='^'||input[pos]==='_'){const kind=input[pos++],v=atom();if(n.type!=='scripts')n={type:'scripts',a:n};n[kind==='^'?'sup':'sub']=v}children.push(n)}if(end)throw Error('Feche todas as chaves da fórmula.');return{type:'row',children}};return row()}
function markup(n){if(n.type==='text')return`<${/[0-9]/.test(n.text)?'mn':/[a-zA-Zα-ωΑ-Ω]/.test(n.text)?'mi':'mo'}>${esc(n.text)}</${/[0-9]/.test(n.text)?'mn':/[a-zA-Zα-ωΑ-Ω]/.test(n.text)?'mi':'mo'}>`;if(n.type==='row')return`<mrow>${n.children.map(markup).join('')}</mrow>`;if(n.type==='normal')return`<mstyle mathvariant="normal">${markup(n.a)}</mstyle>`;if(n.type==='frac')return`<mfrac>${markup(n.a)}${markup(n.b)}</mfrac>`;if(n.type==='sqrt')return`<msqrt>${markup(n.a)}</msqrt>`;if(n.type==='over')return`<mover>${markup(n.a)}${markup(n.b)}</mover>`;if(n.type==='scripts'){const tag=n.sup&&n.sub?'msubsup':n.sup?'msup':'msub';return`<${tag}>${markup(n.a)}${n.sub?markup(n.sub):''}${n.sup?markup(n.sup):''}</${tag}>`}return''}
export function mathHTML(text){try{return`<math xmlns="http://www.w3.org/1998/Math/MathML" display="block" aria-label="${esc(text)}">${markup(parseMath(text))}</math>`}catch(e){return`<span style="font:14px Arial;color:#a64f56">${esc(e.message)}</span>`}}
export function drawMath(ctx,text,x,y,size,color){let ast;try{ast=parseMath(text)}catch{ctx.font=size+'px Georgia';ctx.fillStyle=color;ctx.fillText(text,x,y+size);return}const measure=(n,s)=>{ctx.font=s+'px Georgia';if(n.type==='text'){const w=ctx.measureText(n.text).width;return{w,up:s*.8,down:s*.25,draw:(x,y)=>{ctx.font=s+'px Georgia';ctx.fillText(n.text,x,y)}}}if(n.type==='normal')return measure(n.a,s);if(n.type==='row'){const cs=n.children.map(c=>measure(c,s));return{w:cs.reduce((a,c)=>a+c.w,0),up:Math.max(s*.8,...cs.map(c=>c.up)),down:Math.max(s*.25,...cs.map(c=>c.down)),draw:(x,y)=>{for(const c of cs){c.draw(x,y);x+=c.w}}}}if(n.type==='frac'){const a=measure(n.a,s*.8),b=measure(n.b,s*.8),w=Math.max(a.w,b.w)+s*.3;return{w,up:a.up+a.down+s*.35,down:b.up+b.down+s*.05,draw:(x,y)=>{a.draw(x+(w-a.w)/2,y-s*.35-a.down);b.draw(x+(w-b.w)/2,y+s*.15+b.up);ctx.beginPath();ctx.moveTo(x,y-s*.15);ctx.lineTo(x+w,y-s*.15);ctx.stroke()}}}if(n.type==='sqrt'){const a=measure(n.a,s);return{w:a.w+s*.7,up:a.up+s*.15,down:a.down,draw:(x,y)=>{ctx.font=s*1.2+'px Georgia';ctx.fillText('√',x,y);a.draw(x+s*.65,y);ctx.beginPath();ctx.moveTo(x+s*.6,y-a.up-s*.06);ctx.lineTo(x+s*.7+a.w,y-a.up-s*.06);ctx.stroke()}}}if(n.type==='scripts'){const a=measure(n.a,s),sup=n.sup&&measure(n.sup,s*.65),sub=n.sub&&measure(n.sub,s*.65);return{w:a.w+Math.max(sup?.w||0,sub?.w||0),up:Math.max(a.up,sup?sup.up+s*.6:0),down:Math.max(a.down,sub?sub.down+s*.3:0),draw:(x,y)=>{a.draw(x,y);sup?.draw(x+a.w,y-s*.6);sub?.draw(x+a.w,y+s*.3)}}}if(n.type==='over'){const a=measure(n.a,s*1.3),b=measure(n.b,s*.5),w=Math.max(a.w,b.w)+s*.1;return{w,up:a.up+b.up+b.down,down:a.down,draw:(x,y)=>{a.draw(x+(w-a.w)/2,y);b.draw(x+(w-b.w)/2,y-a.up-s*.15)}}}};const box=measure(ast,size);ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=Math.max(1,size/26);ctx.textAlign='left';box.draw(x,y+box.up);return box}
